theorem pairing_tendsto {α : Type*} {l : Filter α}
    (M : E →L[𝕜] E) {u v : α → E} {u₀ v₀ : E}
    (hu : Filter.Tendsto u l (nhds u₀)) (hv : Filter.Tendsto v l (nhds v₀)) :
    Filter.Tendsto (fun n => inner 𝕜 (u n) (M (v n))) l
      (nhds (inner 𝕜 u₀ (M v₀)))

theorem exists_walkWord_of_mem_closure (s : Finset Γ) {g : Γ}
    (hg : g ∈ Submonoid.closure (s : Set Γ)) :
    ∃ (n : ℕ) (w : WalkWord s n), walkEndpoint s n 1 w = g

theorem mem_sequenceL2_of_bound {ι : Type*} {f : ι → ℂ} {b : ι → ℝ}
    (hb : Summable (fun i => b i ^ 2)) (hbound : ∀ i, ‖f i‖ ≤ b i) :
    Memℓp f 2

theorem mem_countingL2_of_bound {v : X → ℂ} {b : X → ℝ}
    (hb : Summable (fun x => b x ^ 2)) (hbound : ∀ x, ‖v x‖ ≤ b x) :
    MemLp v 2 Measure.count

theorem quadratic_bound_spectrum (P : E →L[ℂ] E) {q : ℝ} (hq : 0 ≤ q)
    (hP : ∀ v, ‖inner ℂ (P v) v‖ ≤ q * ‖v‖ ^ 2) {k : ℂ}
    (hk : k ∈ spectrum ℂ P) : ‖k‖ ≤ q

theorem frequency_matrix_has_kernel {N : ℕ}
    (B : (Fin (N + 1) → ℂ) →ₗ[ℂ] (Fin N → ℂ)) :
    ∃ v, v ≠ 0 ∧ B v = 0

theorem orthogonalProjection_congr {S T : Submodule ℂ E}
    [S.HasOrthogonalProjection] [T.HasOrthogonalProjection] (h : S = T) (x : E) :
    (S.orthogonalProjectionOnto x : E) = (T.orthogonalProjectionOnto x : E)

theorem exists_measurable_unit_kernel {B : Ω → E →L[ℂ] F}
    (hB : Measurable B) (hker : ∀ ω, ∃ v, v ≠ 0 ∧ B ω v = 0) :
    ∃ v : Ω → E, Measurable v ∧ (∀ ω, ‖v ω‖ = 1) ∧ (∀ ω, B ω (v ω) = 0)

theorem bandPiece_memLp {d : ℕ} (q : ℝ) {v : ℝ → EuclideanSpace ℂ (Fin d)}
    (hv : Measurable v) (hnorm : ∀ ω, ‖v ω‖ = 1) (l : Fin d) :
    MemLp (bandPiece q v l) 2 volume

theorem finiteBand_on_cell {d : ℕ} {q : ℝ} (hq : 0 < q)
    (v : ℝ → EuclideanSpace ℂ (Fin d)) (l : Fin d) {ω : ℝ}
    (hω : ω ∈ Ico 0 q) : finiteBand q v (ω + (l : ℕ) * q) = v ω l

theorem compactBoundaryEmbedding_retraction {p : OnePoint ℂ}
    (hp : p ∈ compactHyperbolicBoundary) :
    compactBoundaryEmbedding (compactBoundaryRetraction p) = p

theorem compactBoundaryRetraction_smul (g : SL(2, ℝ)) {p : OnePoint ℂ}
    (hp : p ∈ compactHyperbolicBoundary) :
    compactBoundaryRetraction (g • p) = g • compactBoundaryRetraction p

theorem mutuallySingular_map_iff_of_embedding {X Y : Type*}
    [MeasurableSpace X] [MeasurableSpace Y] (f : X → Y) (hf : MeasurableEmbedding f)
    (μ ν : Measure X) : Measure.map f μ ⟂ₘ Measure.map f ν ↔ μ ⟂ₘ ν

theorem boundaryPoleMatrix_norm_tendsto {α : Type*} {l : Filter α}
    (ξ : ℝ) (z : α → ℍ) (hz : Tendsto (fun n => (z n : ℂ)) l (𝓝 (ξ : ℂ))) :
    Tendsto (fun n => ‖((boundaryPoleMatrix ξ • z n : ℍ) : ℂ)‖) l atTop

theorem finiteBoundaryRadialChart_tendsto {α : Type*} {l : Filter α}
    (ξ : ℝ) (z : α → ℍ) (hz : Tendsto (fun n => (z n : ℂ)) l (𝓝 (ξ : ℂ))) :
    Tendsto (fun n => axisRadialCoordinate (finiteBoundaryRadialChart ξ • z n)) l atTop

theorem hyperbolicGrid_diameter {R : ℝ} {z w : ℍ}
    (hz : dist z UpperHalfPlane.I ≤ R) (hw : dist w UpperHalfPlane.I ≤ R)
    (hcell : hyperbolicGrid R z = hyperbolicGrid R w) : dist z w ≤ 2

theorem hyperbolic_ball_coordinates {z : ℍ} {R : ℝ}
    (hz : dist z UpperHalfPlane.I ≤ R) :
    Real.exp (-R) ≤ z.im ∧ z.im ≤ Real.exp R ∧ |z.re| ≤ Real.exp R

theorem exists_positive_logDensity_window {B : Type*} [MeasurableSpace B]
    (ν m : Measure B) (hν : 0 < ν univ) :
    ∃ M : ℝ, 0 ≤ M ∧ 0 < ν {ξ | |Real.log ((ν.rnDeriv m ξ).toReal)| ≤ M}

theorem measurableSet_logDensity_window {B : Type*} [MeasurableSpace B]
    (ν m : Measure B) (M : ℝ) :
    MeasurableSet {ξ | |Real.log ((ν.rnDeriv m ξ).toReal)| ≤ M}

theorem preimage_cocycleDeficitShadow (ν : Measure B) (D : Γ → ℝ) (R : ℝ) (g : Γ) :
    (fun ξ : B => g • ξ) ⁻¹' cocycleDeficitShadow ν D R g =
      {ξ | D g - stationaryLogCocycle ν g ξ ≤ R}

theorem finiteMeasure_tendsto_zero_of_absolutelyContinuous {X I : Type*}
    [MeasurableSpace X] (ν m : Measure X) [IsFiniteMeasure ν] [SigmaFinite m]
    (hac : ν ≪ m) (S : I → Set X) {l : Filter I}
    (hS : Tendsto (fun i => m (S i)) l (𝓝 0)) :
    Tendsto (fun i => ν (S i)) l (𝓝 0)

theorem integrable_inner_operator_prod {E F : Type*}
    [NormedAddCommGroup E] [InnerProductSpace ℂ E] [NormedSpace ℝ E] [IsScalarTower ℝ ℂ E] [CompleteSpace E]
    [NormedAddCommGroup F] [InnerProductSpace ℂ F] [NormedSpace ℝ F] [IsScalarTower ℝ ℂ F] [CompleteSpace F]
    (M : F →L[ℂ] E) {u : ℝ → E} {v : ℝ → F}
    (hu : Integrable u) (hv : Integrable v) :
    Integrable (fun p : ℝ × ℝ => inner ℂ (u p.1) (M (v p.2))) (volume.prod volume)

theorem exists_maximal_atom {X : Type*} [MeasurableSpace X] [MeasurableSingletonClass X]
    (ν : Measure X) [IsFiniteMeasure ν] (h : ∃ x : X, ν {x} ≠ 0) :
    ∃ x : X, 0 < ν {x} ∧ ∀ y : X, ν {y} ≤ ν {x}

theorem UniformNorthSouth.conjugate {g : G} {p q : X}
    (h : UniformNorthSouth g p q) (b : G) :
    UniformNorthSouth (b * g * b⁻¹) (b • p) (b • q)

theorem no_invariantMean_of_northSouth_conjugate [T2Space X] {g : G} {p q : X}
    (h : UniformNorthSouth g p q) (b : G)
    (hdistinct : Function.Injective (fun z : Bool × Bool =>
      if z.1 then b • (if z.2 then p else q) else (if z.2 then p else q))) :
    ¬HasInvariantMean G

theorem northSouth_conjugate_free_powers [T2Space X] {g : G} {p q : X}
    (h : UniformNorthSouth g p q) (b : G)
    (hdistinct : Function.Injective (fun z : Bool × Bool =>
      if z.1 then b • (if z.2 then p else q) else (if z.2 then p else q))) :
    ∃ n : ℕ, 0 < n ∧ Function.Injective
      (FreeGroup.lift (fun i : Bool => if i then (b * g * b⁻¹) ^ n else g ^ n))
